The `app/router.tsx` file configures TanStack Router. It imports a route tree (which is automatically generated) and allows control for options like scroll restoration. Add the following to the file and save it:
```
// app/router.tsx
import { createRouter as createTanStackRouter } from '@tanstack/react-router';
import { routeTree } from './routeTree.gen';
export function createRouter() {
  const router = createTanStackRouter({
    routeTree,
    scrollRestoration: true,
  });
  return router;
}
